      need(plan.schema===COLLECTION&&typeof prepareSnapshot==='function','WORKSPACE_RECOVERY_CAPTURE_HOOK_INVALID');
      application=await prepareSnapshot({staged,stateRoot:plan.stateRoot,plan});
